jQuery(document).ready(function($) {
    // Vérifier si nous sommes sur la page d'accueil
    if (!$('body').hasClass('home')) {
        function adjustFooterPosition() {
            // Trouver tous les éléments en position absolute
            var absoluteElements = $('*').filter(function() {
                return $(this).css('position') === 'absolute';
            });

            if (absoluteElements.length > 0) {
                // Trouver l'élément le plus bas
                var maxBottom = 0;
                absoluteElements.each(function() {
                    var bottom = $(this).offset().top + $(this).outerHeight();
                    maxBottom = Math.max(maxBottom, bottom);
                });

                // Ajuster la marge en fonction de la taille de l'écran
                if (window.innerWidth <= 544) {
                    maxBottom -= 46;
                } else {
                    maxBottom -= 35;
                }

                // Appliquer la hauteur minimale au conteneur principal
                $('#content').css('min-height', maxBottom + 'px');
            }

            // Ajouter la classe pour afficher le footer
            $('body').addClass('footer-ready');
        }

        // Exécuter immédiatement
        setTimeout(adjustFooterPosition, 0);

        // Exécuter après le chargement complet de la page
        $(window).on('load', adjustFooterPosition);

        // Exécuter lors du redimensionnement de la fenêtre
        $(window).on('resize', adjustFooterPosition);
    }

    // Pour le contenu dynamique, vous pouvez appeler adjustFooterPosition()
    // après chaque modification du contenu
});
